<script setup lang="ts">import{computed}from"vue";import{buildProviderSummaries}from"@/domain/providers/statistics";import type{ExternalSourceRecord,SyncJobRecord}from"@/domain/providers/records";const props=defineProps<{sources:ExternalSourceRecord[];jobs:SyncJobRecord[]}>();const summaries=computed(()=>buildProviderSummaries(props.sources,props.jobs));const date=(v?:string)=>v?new Intl.DateTimeFormat("pt-PT",{dateStyle:"medium",timeStyle:"short"}).format(new Date(v)):"Nunca";</script><template><section class="provider-dashboard" aria-labelledby="provider-dashboard-title"><h2 id="provider-dashboard-title">Resumo por provider</h2><div class="provider-card-grid"><article v-for="item in summaries" :key="item.provider" class="provider-card"><header><h3>{{item.provider}}</h3><span v-if="item.failedJobs" class="status-danger">{{item.failedJobs}} falhas</span></header><dl><div><dt>Fontes</dt><dd>{{item.sources}}</dd></div><div><dt>Títulos</dt><dd>{{item.titles}}</dd></div><div><dt>Principais</dt><dd>{{item.primary}}</dd></div><div><dt>Em execução</dt><dd>{{item.runningJobs}}</dd></div></dl><small>Última sincronização: {{date(item.lastSync)}}</small></article></div></section></template>
